/* Общие звуки, подсказки и визуальные эффекты. Звуки синтезируются браузером без внешних файлов. */
(()=>{'use strict';let context;let enabled=localStorage.getItem('cifrogator_sound')==='on';const button=document.getElementById('sound');function audio(){try{context??=new (window.AudioContext||window.webkitAudioContext)();if(context.state==='suspended')context.resume();return context}catch{return null}}function tone(freq=500,duration=.12,type='sine',delay=0,volume=.08){if(!enabled)return;const c=audio();if(!c)return;const o=c.createOscillator(),g=c.createGain(),t=c.currentTime+delay;o.type=type;o.frequency.setValueAtTime(freq,t);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(volume,t+.018);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g);g.connect(c.destination);o.start(t);o.stop(t+duration+.02)}function play(kind){if(kind==='win'){tone(523,.16,'sine');tone(659,.16,'sine',.12);tone(784,.26,'sine',.25)}else if(kind==='wrong'){tone(250,.17,'triangle');tone(200,.2,'triangle',.14)}else if(kind==='finish'){[523,659,784,1047].forEach((f,i)=>tone(f,.32,'sine',i*.13))}else tone(580,.075,'sine')}window.cifSound=play;window.toggleSound=()=>{enabled=!enabled;localStorage.setItem('cifrogator_sound',enabled?'on':'off');if(enabled){audio();play('win')}updateSound()};function updateSound(){if(button){button.textContent=enabled?'🔊':'🔇';button.title=enabled?'Отключить звуки':'Включить звуки';button.setAttribute('aria-label',button.title)}}updateSound();document.addEventListener('click',e=>{if(e.target.closest('button,a.age,.building')&&!e.target.closest('#sound'))play('tap')});let toastTimer;window.cifToast=(msg)=>{let el=document.querySelector('.fx-toast');if(!el){el=document.createElement('div');el.className='fx-toast';el.setAttribute('role','status');document.body.appendChild(el)}el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400)};window.cifCelebrate=()=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<32;i++){const p=document.createElement('span');p.className='fx-confetti';p.style.left=(40+Math.random()*20)+'vw';p.style.top=(30+Math.random()*25)+'vh';p.style.background=['#65e8ff','#baff73','#ffdf65','#ff83b8'][i%4];p.style.setProperty('--dx',(Math.random()*500-250)+'px');p.style.setProperty('--dy',(Math.random()*450-120)+'px');p.style.setProperty('--rot',(Math.random()*720)+'deg');document.body.appendChild(p);setTimeout(()=>p.remove(),1100)}};const help=document.createElement('button');help.className='help-btn';help.textContent='?';help.title='Как играть';help.setAttribute('aria-label','Как играть');const popup=document.createElement('div');popup.className='fx-help';popup.hidden=true;popup.innerHTML='<strong>Как играть?</strong><div>Выбери возраст, открой здание кибергорода, прочитай подсказку и ответь на вопросы. За правильные ответы получай баллы. Пройди все 5 тем, чтобы открыть сертификат. Звуки можно отключить кнопкой 🔊.</div>';help.addEventListener('click',()=>{popup.hidden=!popup.hidden;play('tap')});document.body.append(help,popup);document.addEventListener('keydown',e=>{if(e.key==='Escape'){popup.hidden=true;if(typeof window.closeM==='function')window.closeM()}})})();
